"""Flat colour illustrations, Top-3000 nouns batch 3 (100 words). Same polygon pipeline as svgator_top3000_1.py.
Run: python3 Tools/svgator_top3000_3.py   (then svg_lint on the new files, validate_svg_assets.py, swift test)
"""

import math
import sys

import svgator_top3000_1 as base
from svgator_top3000_1 import BR, CR, DT, GN, GS, GY, HL, IN, OR, PK, R, SB, SD, SK, SS, TL, O, P


def star(cx, cy, ro, ri, n, c):
    return P([(round(cx + (ro if i % 2 == 0 else ri) * math.cos(math.pi * i / n - math.pi / 2)),
               round(cy + (ro if i % 2 == 0 else ri) * math.sin(math.pi * i / n - math.pi / 2))) for i in range(2 * n)], c)


def ring(cx, cy, r, n, rr, c):
    return [O(round(cx + r * math.cos(2 * math.pi * i / n)), round(cy + r * math.sin(2 * math.pi * i / n)), rr, rr, c) for i in range(n)]


def boat(x, s=1):
    return [P([(x, 130), (x + 50 * s, 130), (x + 40 * s, 146), (x + 10 * s, 146)], BR), P([(x + 24 * s, 100), (x + 24 * s, 128), (x + 46 * s, 128)], CR), R(x + 23 * s, 96, 2, 34, BR)]


